import React from 'react';
import { motion } from 'framer-motion';

const AttentionHeatmap = ({ days }) => {
  if (!days?.length) return null;
  const maxImp = Math.max(...days.map(d => d.importance), 1e-9);

  // Compute attention entropy for diagnostic display
  // Low entropy = focused, high entropy = diffuse
  const totalImp = days.reduce((s, d) => s + d.importance, 0);
  const entropy = days.reduce((s, d) => {
    const p = d.importance / (totalImp + 1e-10);
    return s - (p > 0 ? p * Math.log2(p + 1e-10) : 0);
  }, 0);
  const maxEntropy = Math.log2(days.length);
  const focusScore = Math.max(0, ((1 - entropy / maxEntropy) * 100)).toFixed(0);

  return (
    <motion.div
      className="card attention-heatmap-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, delay: 0.18 }}
    >
      <div className="card-title">
        <div className="card-ico ico-p">👁️</div>
        <span className="card-title-text">Temporal Attention Weights</span>
        <span style={{
          marginLeft: 'auto', fontFamily: 'JetBrains Mono,monospace',
          fontSize: 9, color: focusScore > 30 ? 'var(--green)' : 'var(--dim)',
          letterSpacing: '.06em'
        }}>
          FOCUS: {focusScore}%
        </span>
      </div>

      <div className="sub-note">
        Top-weighted historical days within 60-step lookback (best attention head, temperature-sharpened)
      </div>

      <div className="day-list">
        {days.map((day, i) => {
          const pct = (day.importance / maxImp) * 100;
          const label = day.days_ago === 0 ? 'Today' : `${day.days_ago}d ago`;
          return (
            <motion.div
              key={day.day_index}
              className="day-item"
              initial={{ opacity: 0, x: 16 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.2 + i * 0.08 }}
            >
              <span className="day-rank">#{i + 1}</span>
              <div className="day-info">
                <div className="day-label">{label}</div>
                <div className="day-importance">t-{day.days_ago}</div>
              </div>
              <div className="day-bar">
                <motion.div
                  className="day-bar-fill"
                  initial={{ width: 0 }}
                  animate={{ width: `${pct}%` }}
                  transition={{ duration: 0.9, delay: 0.3 + i * 0.08 }}
                />
              </div>
              <span className="day-imp-val">{day.importance.toFixed(4)}</span>
            </motion.div>
          );
        })}
      </div>

      <div className="tip-box" style={{ marginTop: 16 }}>
        💡 Weights from highest-variance attention head, re-sharpened (τ=0.5). Focus score measures attention concentration (0%=uniform, 100%=single-day).
      </div>
    </motion.div>
  );
};

export default AttentionHeatmap;
